contact=photo_intro('Contact Us','Connect with our team about products, partnerships and opportunities.','contact-banner-v2.png')+'<section class="wrap consultation section"><div class="contact-copy"><h2>Let’s connect.</h2><p>At Nanolite, we are always here to assist with inquiries or business opportunities. Whether you’re interested in our CLC blocks, exploring franchise opportunities, or have questions about our solutions, we would love to hear from you.</p><p>Our team of experts is ready to provide guidance, share insights, and offer support for your project.</p><a class="contact-email" href="mailto:management@nanolite.co">management@nanolite.co</a><p class="contact-phone"><a href="tel:+17189124171">+1 718 912 4171</a><br><a href="tel:+923325055665">+92 332 505 5665</a></p><h3>Office locations</h3><div class="offices">'+''.join(f'<div><h3>{e(name)}</h3><address>{e(address)}</address></div>' for name,address in offices)+'</div><h3 class="hours-title">Business hours</h3><p>Monday–Friday: 9:00 AM–6:00 PM<br>Saturday: 10:00 AM–2:00 PM<br>Sunday: Closed</p></div><aside class="consultation-form" id="inquiry">'+expertform.replace('Talk to our team.','Send an inquiry.').replace('Your question','Your message').replace('Tell us what you are working on.','Tell us how we can help.')+'</aside></section>'
